jsLib:
function Url() {
    const { source, java } = this;
    var original = {
        "sourceurl": "https://www.mhtmh.com",
        "Urls": []
    };
    if (source.getVariable() == '') {
        source.setVariable(JSON.stringify(original, null, "\t"));
        java.toast('已初始化');
    }
    return JSON.parse(source.getVariable()).sourceurl;
}

